-- Registry of tenants (plan sections 6.5 and 9). The registry is not tenant-scoped, so everything lives in one
-- shared schema. Ids are UUIDv7 generated by the service; timestamps come from the service clock, which keeps
-- cursors exact (millisecond precision).
-- Constraints are the last guard (DM-10); foreign keys exist only inside this database (DM-02).

CREATE SCHEMA IF NOT EXISTS shared;

CREATE TABLE shared.tenants (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL CONSTRAINT tenants_name_length CHECK (char_length(name) BETWEEN 1 AND 100),
    slug       text        NOT NULL CONSTRAINT tenants_slug_format CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
    status     text        NOT NULL DEFAULT 'active' CONSTRAINT tenants_status_values CHECK (status IN ('active', 'suspended')),
    created_by text        NOT NULL,
    created_at timestamptz NOT NULL,
    CONSTRAINT tenants_slug_key UNIQUE (slug)
);

CREATE INDEX tenants_created_idx ON shared.tenants (created_at, id);

CREATE TABLE shared.memberships (
    tenant_id  uuid        NOT NULL REFERENCES shared.tenants (id),
    user_id    text        NOT NULL,
    role       text        NOT NULL CONSTRAINT memberships_role_values CHECK (role IN ('trader', 'tenant-admin')),
    joined_at  timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (tenant_id, user_id),
    -- A user belongs to one tenant only.
    CONSTRAINT memberships_user_id_key UNIQUE (user_id)
);

CREATE INDEX memberships_joined_idx ON shared.memberships (tenant_id, joined_at, user_id);

CREATE TABLE shared.invite_codes (
    -- SHA-256 hex of the code: the code is shown once, at creation, and never stored.
    code_hash  text        PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES shared.tenants (id),
    role       text        NOT NULL CONSTRAINT invite_codes_role_values CHECK (role IN ('trader', 'tenant-admin')),
    max_uses   integer     NOT NULL CONSTRAINT invite_codes_max_uses_positive CHECK (max_uses > 0),
    uses       integer     NOT NULL DEFAULT 0,
    expires_at timestamptz NOT NULL,
    created_by text        NOT NULL,
    created_at timestamptz NOT NULL,
    CONSTRAINT invite_codes_uses_range CHECK (uses >= 0 AND uses <= max_uses)
);

CREATE INDEX invite_codes_tenant_idx ON shared.invite_codes (tenant_id);

-- Transactional outbox (REL-01): written in the same transaction as the data change, published by the relay.
CREATE TABLE shared.outbox (
    id           uuid        PRIMARY KEY,
    aggregate_id text        NOT NULL,
    -- NATS subject, for example chance.tenants.TenantCreated.<tenantId>.
    subject      text        NOT NULL,
    type         text        NOT NULL,
    -- The whole CloudEvent.
    payload      jsonb       NOT NULL,
    created_at   timestamptz NOT NULL,
    published_at timestamptz,
    attempts     integer     NOT NULL DEFAULT 0,
    last_error   text
);

CREATE INDEX outbox_unpublished_idx ON shared.outbox (created_at) WHERE published_at IS NULL;
